function totalSpread(nums: number[]): number {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let hi = nums[i], lo = nums[i];
    for (let j = i; j < nums.length; j++) {
      hi = Math.max(hi, nums[j]);
      lo = Math.min(lo, nums[j]);
      total += hi - lo;
    }
  }
  return total;
}

