function totalSpread(nums: number[]): number {
  const n = nums.length;
  // sign = 1: sum of subarray maxima; sign = -1: sum of subarray minima (compare negated values)
  const sumExtreme = (sign: number): number => {
    const stack: number[] = [];
    let sum = 0;
    for (let i = 0; i <= n; i++) {
      while (stack.length && (i === n || sign * nums[stack[stack.length - 1]] <= sign * nums[i])) {
        const j = stack.pop()!;
        const left = j - (stack.length ? stack[stack.length - 1] : -1);
        sum += nums[j] * left * (i - j);
      }
      stack.push(i);
    }
    return sum;
  };
  return sumExtreme(1) - sumExtreme(-1);
}

