class Solution:
    def totalSpread(self, nums: List[int]) -> int:
        n = len(nums)

        def sum_extreme(sign):
            # sign = 1 sums subarray maxima, sign = -1 sums subarray minima
            stack, total = [], 0
            for i in range(n + 1):
                while stack and (i == n or sign * nums[stack[-1]] <= sign * nums[i]):
                    j = stack.pop()
                    left = j - (stack[-1] if stack else -1)
                    total += nums[j] * left * (i - j)
                stack.append(i)
            return total

        return sum_extreme(1) - sum_extreme(-1)

